const allowed = new Set(['Casa','Beleza','Eletrônicos','Moda','Pet']);
const seen = new Set();
const input = $input.all().flatMap(i => Array.isArray(i.json.products) ? i.json.products : [i.json]);

const candidates = [];

for (const p of input) {
  const name = String(p.name ?? '').trim();
  const price = Number(p.price);
  const category = String(p.category ?? '').trim();
  const link = String(p.affiliateLink ?? p.link ?? '').trim();
  const productId = String(p.productId ?? name).trim();
  const priceConfirmed = p.priceConfirmed === true;
  const discountConfirmed = p.discountConfirmed === true;

  if (!name || !link || !productId) continue;
  if (!allowed.has(category)) continue;
  if (!Number.isFinite(price) || price < 10 || price > 1000) continue;
  if (!priceConfirmed) continue;

  const key = productId.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  const sales = Number(p.sales ?? 0);
  const discount = Number(p.discountPercent ?? 0);
  const commission = Number(p.commissionPercent ?? 0);

  // Pontuação objetiva; campos ausentes valem zero.
  let score = 0;
  if (discountConfirmed && discount > 0) score += Math.min(discount, 40);
  if (sales > 0) score += Math.min(Math.log10(sales + 1) * 8, 30);
  if (commission > 0) score += Math.min(commission, 20);
  if (price <= 100) score += 10;

  candidates.push({
    ...p,
    name, price, category, affiliateLink: link, productId,
    discountConfirmed,
    score: Number(score.toFixed(2))
  });
}

// Ordenação: maior oportunidade primeiro; em empate, menor preço.
candidates.sort((a,b) => b.score - a.score || a.price - b.price);

return candidates.slice(0, 10).map((p, i) => ({
  json: {
    ...p,
    position: i + 1,
    scheduledTime: ['09:00','10:30','12:00','13:30','15:00','16:30','18:00','19:30','21:00','22:30'][i],
    status: 'fila',
    copy:
`💗 ACHADINHO DA THAY!

Gente, olha esse achadinho 😍

🛍️ ${p.name}
💰 R$ ${p.price.toFixed(2).replace('.', ',')}` +
(p.discountConfirmed && p.discountPercent ? `\n🔥 ${p.discountPercent}% de desconto` : '') +
`\n\n🛒 QUERO VER:\n👇\n${p.affiliateLink}\n\n⚠️ Preço e condições podem mudar. Confira no anúncio.`
  }
}));

return $input.all().map(item => ({
  json: {
    ...item.json,
    readyToPublish: true,
    destination: 'Achadinhos da Thay'
  }
}));
